      var t=item.topic,pr=t.practicals||[],sw=t.selfWork||[],pdf=t.pdfPracticals||[];
      var taskHtml="";
      pr.forEach(function(p,i){taskHtml+='<div class="task"><b>Практическая работа '+esc(p.code||("№"+(i+1)))+': '+esc(p.title||"Практическое задание")+'</b><p><b>Цель:</b> '+esc(p.goal||"Закрепить знания по теме.")+'</p><p>'+esc(p.task||p.description||"Выполните задание по материалам темы.")+'</p>'+(p.variants&&p.variants.length?'<p><b>Вариант:</b> '+p.variants.map(esc).join("<br>")+'</p>':"")+'</div>';});
      sw.forEach(function(p,i){taskHtml+='<div class="task"><b>Самостоятельная работа '+esc(p.code||("№"+(i+1)))+': '+esc(p.title||"Задание")+'</b><p>'+esc(p.task||p.description||"Выполните самостоятельное задание по теме.")+'</p></div>';});
      pdf.forEach(function(p){taskHtml+='<div class="task"><b>'+esc(p.title||"Методические указания")+'</b><p>'+esc(p.description||p.task||"Используйте выданные преподавателем материалы.")+'</p></div>';});
      if(!taskHtml)taskHtml='<div class="task"><b>Задание 1. Анализ темы</b><p>Сформулируйте производственную задачу, для решения которой применяются знания по теме «'+esc(t.title)+'». Укажите исходные данные, ограничения и ожидаемый результат.</p></div><div class="task"><b>Задание 2. Алгоритм действий</b><p>Составьте последовательность выполнения работы. Обоснуйте каждый этап и укажите контрольные точки.</p></div><div class="task"><b>Задание 3. Контроль качества</b><p>Определите критерии оценки результата, возможные ошибки и способы их предупреждения.</p></div>';
      var lectures=(t.lectures||[]).filter(function(l){return l&&l.content;});
      var lectureHtml=lectures.map(function(l,li){var body=safeLectureHtml(l.content);return '<article class="lecture-content"><h3>'+esc(l.title||"Материал лекции")+'</h3>'+body+'</article>'+englishTextBlock(l,li);}).join("");
      var studySummary=lectureStudySummary(lectures);
      var extrasHtml=topicExtras(id,t);
      var testQuestions=t.test||[];
      var checkHtml=testQuestions.length?'<section class="self-check"><h3>🧠 Самопроверка по теме</h3><ol>'+testQuestions.map(function(q){return '<li><b>'+esc(q.q||q.question||"Вопрос")+'</b>'+(q.options&&q.options.length?'<ul>'+q.options.map(function(o){return '<li>'+esc(o)+'</li>';}).join("")+'</ul>':"")+'</li>';}).join("")+'</ol><details><summary>Открыть ответы для самопроверки</summary><ol>'+testQuestions.map(function(q){var n=Number(q.correct);return '<li>'+esc(q.options&&q.options[n]!=null?q.options[n]:"Ответ в исходном тесте не указан")+'</li>';}).join("")+'</ol></details></section>':"";
      var comments=["Лайфхак технолога: сначала проверь исходные данные, потом запускай команду. Ctrl+Z — полезная кнопка, но не технологический процесс.","Маленькая производственная мудрость: точность начинается не у станка, а с внимательного чтения задания.","Если что-то не сходится — не гадай. Вернись к чертежу, координатам и условиям задачи. Это не баг, это повод проверить исходные данные.","Пауза на здравый смысл: безопасность и контроль важнее скорости. Станок не оценит спешку.","Профессиональный уровень — это не «нажал и получилось», а понимание, почему получилось именно так."][index%5];
      return '<section class="sheet"><div class="sheet-head"><span>'+esc(id)+' / РАБОЧАЯ ТЕТРАДЬ</span><span>Лист '+(index+1)+' из '+topics.length+'</span></div><div class="section-label">'+esc(item.section||"Раздел")+'</div><h2>'+esc(t.code||"Тема")+'. '+esc(t.title)+'</h2>'+lectureHtml+studySummary+extrasHtml+checkHtml+'<div class="commentary"><b>💬 Комментарий мастера:</b> '+comments+'</div><div class="outcomes"><b>Планируемый результат:</b> обучающийся объясняет основные положения темы, применяет их при решении учебно-производственной задачи и обосновывает выбор действий.</div>'+taskHtml+writtenPractice(id,t)+notesBlock()+'<div class="answer"><b>Ход выполнения / расчёты / схема:</b><div class="write-lines"></div></div><div class="answer"><b>Вывод:</b><div class="write-lines short"></div></div><div class="teacher-mark">Отметка преподавателя: ____________________ Дата: ______________</div></section>';
