    var referenceAppendix = String(id)==="07.01" ? '<section class="sheet wb-reference"><div class="sheet-head"><span>07.01 / СПРАВОЧНЫЙ РАЗДЕЛ</span><span>Приложение</span></div><div class="section-label">Единый справочник команд</div><h2>Основные G-коды и M-коды</h2><p>Сводная таблица для первичного чтения учебных управляющих программ в типовой Fanuc-подобной системе. Это не универсальный стандарт для всех станков: назначение, формат, параметры циклов и доступность команд проверяют по руководству конкретной стойки, модели станка и постпроцессору.</p><h3>Подготовительные функции G</h3><table class="wb-ref-table"><thead><tr><th>Код</th><th>Назначение</th><th>Примечание</th></tr></thead><tbody><tr><td>G00</td><td>Быстрое позиционирование</td><td>Не задаёт рабочую подачу резания</td></tr><tr><td>G01</td><td>Линейная интерполяция</td><td>Рабочее перемещение с заданной подачей</td></tr><tr><td>G02 / G03</td><td>Круговая интерполяция</td><td>Направление дуги зависит от плоскости и системы координат</td></tr><tr><td>G17 / G18 / G19</td><td>Выбор рабочей плоскости</td><td>XY / XZ / YZ в типовой конфигурации</td></tr><tr><td>G20 / G21</td><td>Дюймовая / метрическая система</td><td>Проверьте единицы до запуска программы</td></tr><tr><td>G28</td><td>Возврат в опорную точку</td><td>Формат и промежуточное перемещение зависят от стойки</td></tr><tr><td>G40</td><td>Отмена компенсации радиуса</td><td>Используется для отмены G41/G42</td></tr><tr><td>G41 / G42</td><td>Компенсация радиуса слева / справа от контура</td><td>Сторона определяется относительно направления движения</td></tr><tr><td>G43</td><td>Компенсация длины инструмента</td><td>Чаще применяется на фрезерных станках; формат H зависит от стойки</td></tr><tr><td>G54–G59</td><td>Рабочие системы координат</td><td>Ноль детали / установки</td></tr><tr><td>G70–G76</td><td>Циклы токарной обработки</td><td>Назначение отдельных циклов и синтаксис сверяйте с руководством токарной стойки</td></tr><tr><td>G80</td><td>Отмена постоянного цикла</td><td>Типично для циклов сверления</td></tr><tr><td>G81–G89</td><td>Постоянные циклы обработки отверстий</td><td>Набор циклов и параметры отличаются по системе ЧПУ</td></tr><tr><td>G90 / G91</td><td>Абсолютное / относительное задание координат</td><td>Проверяйте активный режим перед чтением координат</td></tr><tr><td>G94 / G95</td><td>Режим задания подачи</td><td>В типовых конфигурациях: в минуту / на оборот; уточняйте для стойки</td></tr><tr><td>G96 / G97</td><td>Постоянная скорость резания / постоянная частота вращения</td><td>Характерно для токарных систем; ограничения оборотов задаются отдельно</td></tr><tr><td>G98 / G99</td><td>Режимы, зависящие от типа стойки</td><td>На токарных Fanuc-подобных системах часто подача в минуту / на оборот; в циклах сверления фрезерных систем могут задавать уровень возврата. Не переносите трактовку между типами станков</td></tr></tbody></table><h3>Вспомогательные функции M</h3><table class="wb-ref-table"><thead><tr><th>Код</th><th>Назначение</th><th>Примечание</th></tr></thead><tbody><tr><td>M00</td><td>Программируемый останов</td><td>Остановка выполнения программы</td></tr><tr><td>M01</td><td>Дополнительный останов</td><td>Выполняется при включённом режиме Optional Stop</td></tr><tr><td>M02</td><td>Конец программы</td><td>Поведение после завершения зависит от системы</td></tr><tr><td>M03 / M04</td><td>Вращение шпинделя по / против часовой стрелки</td><td>Направление проверяют по инструкции станка и инструменту</td></tr><tr><td>M05</td><td>Останов шпинделя</td><td>Остановка вращения</td></tr><tr><td>M06</td><td>Смена инструмента</td><td>Реализация зависит от конструкции станка</td></tr><tr><td>M08 / M09</td><td>Включение / выключение СОЖ</td><td>Функции охлаждения могут иметь дополнительные варианты</td></tr><tr><td>M30</td><td>Конец программы и возврат / сброс</td><td>Типовое поведение Fanuc-подобных систем</td></tr><tr><td>M98</td><td>Вызов подпрограммы</td><td>Адрес и формат вызова зависят от стойки</td></tr><tr><td>M99</td><td>Возврат из подпрограммы / завершение подпрограммы</td><td>Точное поведение зависит от контекста вызова</td></tr></tbody></table><div class="wb-warning"><b>Важно.</b> G- и M-коды могут быть модальными, иметь разные значения на токарных и фрезерных стойках или быть переназначены изготовителем. Перед запуском УП обязательно сверяйте команды с руководством конкретного станка, проверяйте активные режимы, ноль детали, инструмент, коррекции и безопасные перемещения. Таблица предназначена для обучения, а не для непосредственного запуска программы.</div></section>' : "";
